<script lang="ts">
 import {onMount,tick} from 'svelte';import BrightnessPanel from './BrightnessPanel.svelte';import {interfaceState} from '../interfaceState.svelte';
 const id=$props.id();let button:HTMLButtonElement,panel:HTMLElement,open=$state(false);
 function position(){if(!open)return;const rect=button.getBoundingClientRect(),width=panel.offsetWidth,height=panel.offsetHeight;panel.style.left=Math.max(12,Math.min(innerWidth-width-12,rect.right-width))+'px';panel.style.top=Math.max(12,Math.min(rect.bottom+10,innerHeight-height-104))+'px';}
 onMount(()=>{window.addEventListener('resize',position);return()=>{window.removeEventListener('resize',position);interfaceState.brightnessPreview=null;};});
</script>
<button bind:this={button} type="button" class="icon-btn brightness-trigger" aria-label="调整页面亮度" aria-expanded={open} aria-controls={id} popovertarget={id} title="页面亮度"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 3v2m0 14v2M3 12h2m14 0h2M6 6l1.5 1.5m9 9L18 18M6 18l1.5-1.5m9-9L18 6"/><circle cx="12" cy="12" r="5"/><path d="M12 7v10M12 7a5 5 0 0 0 0 10" fill="currentColor" stroke="none"/></svg></button>
<div bind:this={panel} id={id} tabindex="-1" role="dialog" popover="auto" class="brightness-popover" aria-label="页面亮度设置" onkeydown={event=>{if(event.key==='Escape'&&!event.defaultPrevented){event.preventDefault();event.stopPropagation();panel.hidePopover();button.focus({preventScroll:true});}}} ontoggle={event=>{open=event.newState==='open';if(open)void tick().then(position);else interfaceState.brightnessPreview=null;}}><button type="button" class="icon-btn brightness-close" aria-label="关闭亮度设置" onclick={()=>{panel.hidePopover();button.focus({preventScroll:true});}}><svg width="16" height="16" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg></button><BrightnessPanel/></div>
<style>.brightness-trigger{width:44px;min-width:44px;height:44px;flex:none}.brightness-close{position:absolute;top:5px;right:5px;width:44px;height:44px;min-width:44px}.brightness-popover{position:fixed;inset:auto;margin:0;z-index:90;width:294px;max-width:calc(100vw - 24px);max-height:calc(100dvh - 130px);overflow:auto;background:var(--xy-panel);color:var(--xy-ink);border:1px solid var(--xy-border);border-radius:12px;padding:18px;box-shadow:0 10px 30px color-mix(in srgb,var(--xy-ink) 16%,transparent);filter:none;opacity:1;translate:0 0;transition:opacity .15s ease-out,translate .15s ease-out}@starting-style{.brightness-popover:popover-open{opacity:0;translate:0 -4px}}</style>
